#!/usr/bin/env python3
"""
Round 169n (culprits), 4 October 2026. Needs round 168p.

Earth at night: a second space basemap, NASA's Black Marble recoloured cool.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ["## Round 169n (4 October)\n\nNeeds round 168p (guards on its heading). No tiles patch. app.js?v=1009.\nReplaces round 168n, which failed (patches/failed): it was made before 167p\nand 168p, and their index.html and test.mjs changes were in its way.\n\n- Asked 4 October: another space-themed basemap beside Deep space, \"Earth at\n  night\" (key night): the planet as seen from orbit after dark, from NASA's\n  Black Marble 2016 (VIIRS, GIBS WMTS epsg3857 best, VIIRS_Black_Marble,\n  GoogleMapsCompatible_Level8, source maxzoom 8). One block (\"Earth at night,\n  a second space basemap\" to \"end of Earth at night\"), after Deep space;\n  layers outline-night-* (NIGHT_IDS), settings in NIGHT.\n- The picture's sodium orange lights are recoloured square by square\n  (nightlights:// protocol, nightTable, nightRecolour, rawPng): each pixel by\n  its brightness, from near-black navy through cobalt to pale ice and a cool\n  bone white. The picture's own spread of light is kept.\n- Over it: faint cold moonlight on the relief (outline-dem hillshade), major\n  roads as lit threads from zoom 7 with a soft glow, smaller roads closer in\n  (Streets and places hides them), fine faint borders, a black sky with a\n  thin cobalt rim. Names: the usual dark picture labels (themedSync leaves\n  them on this basemap). Layer colours \"suited to the basemap\": bright.\n- Tests: ramp rises from dark to light, orange light turns cool, no orange,\n  yellow or green hex, choosing it shows its layers, another basemap hides\n  them. GIBS is blocked from the sandbox, so the recoloured picture was not\n  seen against the live tiles.\n"]

DIFF = ""


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round169n: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 168p" not in h.read_text(encoding="utf-8"):
        sys.exit("round169n: round 168p must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", path, check=False).returncode == 0:
        print("round169n: already applied")
    else:
        r = git("apply", "--3way", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/test.mjs", "map/index.html", check=False)
            sys.exit("round169n: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round169n: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
